using System;
using System.Windows.Forms;

using Libs;
using Global;
using Service;
using DeclarationManager;
using SimsObject;

namespace ScheduleManager.Teaching
{
    public partial class frmTeachingTimeResearchEdit : FormBase
    {
        #region Variables

        private long? lngTeachingTimeResearchID = null;
        private string strDefaultTeacherID = null;
        private int? intDefaultYearID = null;
        private int? intDefaultSemester = null;

        #endregion

        #region Properties

        public long? TeachingTimeResearchID
        {
            get { return lngTeachingTimeResearchID; }
            set { lngTeachingTimeResearchID = value; }
        }

        public string DefaultTeacherID
        {
            get { return strDefaultTeacherID; }
            set { strDefaultTeacherID = value; }
        }

        public int? DefaultYearID
        {
            get { return intDefaultYearID; }
            set { intDefaultYearID = value; }
        }

        public int? DefaultSemester
        {
            get { return intDefaultSemester; }
            set { intDefaultSemester = value; }
        }

        #endregion

        public frmTeachingTimeResearchEdit()
        {
            InitializeComponent();
        }

        #region Support Functions

        private void LoadReferenceData()
        {
            uYearSemester.InitData();
            SIM_TeacherService.InitGridLookUpEdit(lookupTeacherID);
        }

        private void LoadData()
        {
            if (lngTeachingTimeResearchID == null)
            {
                ApplyDefaultValues();
                CalculateSummaryValues();
                return;
            }

            SIM_TeachingTimeResearch obj = new SIM_TeachingTimeResearch();
            obj = obj.Get(lngTeachingTimeResearchID);

            if (obj == null || !obj.IsExist)
            {
                MessageManager.Warning("Không tìm thấy dữ liệu!");
                DialogResult = DialogResult.Cancel;
                Close();
                return;
            }

            lookupTeacherID.EditValue = obj.TeacherID;
            uYearSemester.YearIDEditValue = obj.YearID;
            uYearSemester.SemesterEditValue = obj.Semester;

            txtTeachHour.EditValueDecimal = obj.TeachHour;
            txtResearchHour.EditValueDecimal = obj.ResearchHour;
            txtSavePrev.EditValueDecimal = obj.SavePrev;
            txtResearchNow.EditValueDecimal = obj.ResearchNow;
            txtTotalHour.EditValueDecimal = obj.TotalHour;
            txtSaveNext.EditValueDecimal = obj.SaveNext;
            txtLackHour.EditValueDecimal = obj.LackHour;
            txtResearchContent.EditValue = obj.ResearchContent;
            txtDecisionNo.EditValue = obj.DecisionNo;
        }

        private void ApplyDefaultValues()
        {
            if (strDefaultTeacherID != null && strDefaultTeacherID.Trim() != "")
                lookupTeacherID.EditValue = strDefaultTeacherID;

            if (intDefaultYearID != null)
                uYearSemester.YearIDEditValue = intDefaultYearID;

            if (intDefaultSemester != null)
                uYearSemester.SemesterEditValue = intDefaultSemester;
        }

        private decimal GetDecimalValue(Control.UTextEdit txtControl)
        {
            if (txtControl.EditValueDecimal == null)
                return 0;

            return txtControl.EditValueDecimal.Value;
        }

        private void CalculateSummaryValues()
        {
            decimal decSavePrev = GetDecimalValue(txtSavePrev);
            decimal decResearchNow = GetDecimalValue(txtResearchNow);
            decimal decResearchHour = GetDecimalValue(txtResearchHour);
            decimal decTotalHour = decSavePrev + decResearchNow;
            decimal decLackHour = decResearchHour - decTotalHour;

            if (decLackHour < 0)
                decLackHour = 0;

            txtTotalHour.EditValueDecimal = decTotalHour;
            txtLackHour.EditValueDecimal = decLackHour;
        }

        private bool IsValidData()
        {
            if (lookupTeacherID.EditValue == null
                || lookupTeacherID.EditValue.ToString().Trim() == "")
            {
                MessageManager.Warning("Bạn phải chọn giảng viên!");
                lookupTeacherID.Focus();
                return false;
            }

            if (uYearSemester.YearIDEditValue == null)
            {
                MessageManager.Warning("Bạn phải chọn niên học!");
                uYearSemester.Focus();
                return false;
            }

            if (uYearSemester.SemesterEditValue == null)
            {
                MessageManager.Warning("Bạn phải chọn học kỳ!");
                uYearSemester.Focus();
                return false;
            }

            return true;
        }

        private bool SaveData()
        {
            CalculateSummaryValues();

            SIM_TeachingTimeResearch obj = new SIM_TeachingTimeResearch();
            obj.TeachingTimeResearchID = lngTeachingTimeResearchID;
            obj.TeacherID = lookupTeacherID.EditValue.ToString().Trim();
            obj.YearID = uYearSemester.YearIDEditValueInt32;
            obj.Semester = uYearSemester.SemesterEditValueInt32;
            obj.TeachHour = GetDecimalValue(txtTeachHour);
            obj.ResearchHour = GetDecimalValue(txtResearchHour);
            obj.SavePrev = GetDecimalValue(txtSavePrev);
            obj.ResearchNow = GetDecimalValue(txtResearchNow);
            obj.TotalHour = GetDecimalValue(txtTotalHour);
            obj.SaveNext = GetDecimalValue(txtSaveNext);
            obj.LackHour = GetDecimalValue(txtLackHour);

            if (txtResearchContent.EditValue != null)
                obj.ResearchContent = txtResearchContent.EditValue.ToString().Trim();
            else
                obj.ResearchContent = "";

            if (txtDecisionNo.EditValue != null)
                obj.DecisionNo = txtDecisionNo.EditValue.ToString().Trim();
            else
                obj.DecisionNo = "";

            if (lngTeachingTimeResearchID == null)
                obj.CreatedUser = UserSession.Username;
            else
                obj.UpdatedUser = UserSession.Username;

            if (!obj.AddOrEdit())
            {
                MessageManager.Warning("Không lưu được dữ liệu!");
                return false;
            }

            return true;
        }

        #endregion

        #region Form Actions

        private void frmTeachingTimeResearchEdit_Load(object sender, EventArgs e)
        {
            LoadReferenceData();
            LoadData();

            if (lngTeachingTimeResearchID == null)
                Text = "Thêm giờ nghiên cứu khoa học";
            else
                Text = "Sửa giờ nghiên cứu khoa học";
        }

        private void btnSave_Click(object sender, EventArgs e)
        {
            if (!IsValidData())
                return;

            if (SaveData())
            {
                DialogResult = DialogResult.OK;
                Close();
            }
        }

        private void btnClose_Click(object sender, EventArgs e)
        {
            DialogResult = DialogResult.Cancel;
            Close();
        }

        private void NumericValueChanged(object sender, EventArgs e)
        {
            CalculateSummaryValues();
        }

        #endregion
    }
}

