input.contents:
using System;
using System.Data;
using System.Drawing;
using System.Threading;
using System.Windows.Forms;

using DevExpress.XtraGrid.Views.BandedGrid;

using Libs;
using Global;
using Service;
using DeclarationManager;
using SimsObject;

namespace ScheduleManager.Teaching
{
    public partial class frmBangGioNghienCuuKhoaHoc : FormBase, IForm
    {
        #region Consts

        public const string PERMISSION_VIEW = "frmBangGioNghienCuuKhoaHoc_View";

        #endregion

        #region Variables

        private DataTable dtbData = null;
        private bool bolIsRefresh = false;

        #endregion

        #region IForm Members

        private static frmBangGioNghienCuuKhoaHoc _instance = null;

        public static frmBangGioNghienCuuKhoaHoc Instance
        {
            get
            {
                if (_instance == null)
                    _instance = new frmBangGioNghienCuuKhoaHoc();
                return _instance;
            }
        }

        public void Run(bool isShowDialog)
        {
            FormManager.Run(Instance, isShowDialog);
        }

        #endregion

        public frmBangGioNghienCuuKhoaHoc()
        {
            InitializeComponent();
        }

        #region Support Functions

        private void CheckPermission()
        {
        }

        public void LoadReferenceData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadReferenceData));
            else
            {
                if (bolIsRefresh)
                {
                    uSubjectGroup.RefrehData();
                    uYearSemester.RefrehData();
                }
                else
                {
                    uSubjectGroup.InitData();
                    uYearSemester.InitData();
                }

                SIM_TeacherService.InitGridLookUpEdit(lookupTeacherID);
                bolIsRefresh = false;
            }
        }

        public void LoadData()
        {
            if (InvokeRequired)
                Invoke(new MethodInvoker(LoadData));
            else
            {
                ReadData();
                EndProcess();
            }
        }

        private void ReadData()
        {
            SIM_TeachingTimeResearch obj = new SIM_TeachingTimeResearch();
            string strKeyword = GetKeyword();

            if (IsFullYear())
            {
                dtbData = LoadBothSemestersAndMerge(delegate(int intSemester)
                {
                    return obj.GetDataTable(
                        "SIM_TeachingTimeResearch_Search",
                        "@ScienceID", uSubjectGroup.ScienceEditValue,
                        "@SubjectGroupID", uSubjectGroup.SubjectGroupEditValue,
                        "@TeacherID", lookupTeacherID.EditValue,
                        "@YearID", uYearSemester.YearIDEditValue,
                        "@Semester", intSemester,
                        "@Keyword", strKeyword
                    );
                });
            }
            else
            {
                dtbData = obj.GetDataTable(
                    "SIM_TeachingTimeResearch_Search",
                    "@ScienceID", uSubjectGroup.ScienceEditValue,
                    "@SubjectGroupID", uSubjectGroup.SubjectGroupEditValue,
                    "@TeacherID", lookupTeacherID.EditValue,
                    "@YearID", uYearSemester.YearIDEditValue,
                    "@Semester", uYearSemester.SemesterEditValue,
                    "@Keyword", strKeyword
                );
            }

            if (dtbData == null || dtbData.Rows.Count == 0)
            {
                gcData.DataSource = null;
                MessageManager.Warning("Không có dữ liệu!");
                return;
            }

            ApplyYearTextColumn(dtbData);
            InitGrid();
            gcData.DataSource = dtbData;
            gvData.BestFitColumns();
        }

        private string GetKeyword()
        {
            if (txtKeyword.EditValue == null)
                return null;

            string strKeyword = txtKeyword.EditValue.ToString().Trim();
            if (strKeyword == "")
                return null;

            return strKeyword;
        }

        private bool IsFullYear()
        {
            return uYearSemester.SemesterEditValue == null
                || uYearSemester.SemesterEditValue.ToString().Trim() == "";
        }

        private DataTable LoadBothSemestersAndMerge(
            Func<int, DataTable> loadBySemester)
        {
            DataTable dtbHK1 = loadBySemester(1);
            DataTable dtbHK2 = loadBySemester(2);
            return MergeSemesterData(dtbHK1, dtbHK2);
        }

        private DataTable MergeSemesterData(DataTable dtbHK1, DataTable dtbHK2)
        {
            if (dtbHK1 == null || dtbHK1.Rows.Count == 0)
                return dtbHK2;

            if (dtbHK2 == null || dtbHK2.Rows.Count == 0)
                return dtbHK1;

            DataTable dtbResult = dtbHK1.Clone();

            foreach (DataRow row in dtbHK1.Rows)
                dtbResult.ImportRow(row);

            foreach (DataRow row in dtbHK2.Rows)
                dtbResult.ImportRow(row);

            return dtbResult;
        }

        private void ApplyYearTextColumn(DataTable dt)
        {
            if (!dt.Columns.Contains("YearText"))
                dt.Columns.Add("YearText", typeof(string));

            string strYearText = uYearSemester.YearEditValueText;
            if (strYearText == null)
                strYearText = "";

            foreach (DataRow row in dt.Rows)
                row["YearText"] = strYearText;
        }

        private void InitGrid()
        {
            gvData.Bands.Clear();
            gvData.Columns.Clear();

            GridBand gbData = new GridBand();
            gbData.Caption = "NGHIÊN CỨU KHOA HỌC";
            gbData.AppearanceHeader.Font = new Font("Tahoma", 9, FontStyle.Bold);
            gbData.AppearanceHeader.TextOptions.HAlignment = DevExpress.Utils.HorzAlignment.Center;
            gvData.Bands.Add(gbData);

            AddColumn(gbData, "TeacherName", "Giảng viên", 180, "", DevExpress.Utils.HorzAlignment.Near);
            AddColumn(gbData, "YearText", "Năm học", 100);
            AddColumn(gbData, "Semester", "Học kỳ", 70);
            AddColumn(gbData, "TeachHour", "Định mức giờ giảng dạy", 120, "#,##0.00");
            AddColumn(gbData, "ResearchHour", "Định mức giờ NCKH", 120, "#,##0.00");
            AddColumn(gbData, "SavePrev", "Giờ NCKH bảo lưu năm trước", 130, "#,##0.00");
            AddColumn(gbData, "ResearchNow", "Số giờ NCKH năm nay", 120, "#,##0.00");
            AddColumn(gbData, "TotalHour", "Tổng cộng giờ NCKH", 120, "#,##0.00");
            AddColumn(gbData, "SaveNext", "Giờ NCKH bảo lưu năm sau", 130, "#,##0.00");
            AddColumn(gbData, "LackHour", "Giờ thiếu so với định mức", 130, "#,##0.00");
            AddColumn(gbData, "ResearchContent", "Nội dung nghiên cứu", 250, "", DevExpress.Utils.HorzAlignment.Near);
            AddColumn(gbData, "DecisionNo", "Văn bản quyết định", 180, "", DevExpress.Utils.HorzAlignment.Near);

            HighlightColumn("TotalHour", Color.LightSkyBlue);
            HighlightColumn("LackHour", Color.FromArgb(255, 255, 192));

            gvData.SummaryCollection =
                "TeachHour,ResearchHour,SavePrev,ResearchNow,TotalHour,SaveNext,LackHour";
        }

        private void HighlightColumn(string fieldName, Color backColor)
        {
            BandedGridColumn col = gvData.Columns[fieldName] as BandedGridColumn;
            if (col == null)
                return;

            col.AppearanceCell.BackColor = backColor;
            col.AppearanceCell.Options.UseBackColor = true;
            col.AppearanceCell.Font = new Font("Tahoma", 9, FontStyle.Bold);
            col.AppearanceCell.Options.UseFont = true;
        }

        private void AddColumn(
            GridBand band,
            string fieldName,
            string caption,
            int width,
            string format,
            DevExpress.Utils.HorzAlignment cellAlign)
        {
            BandedGridColumn col = new BandedGridColumn();

            col.FieldName = fieldName;
            col.Caption = caption;
            col.Name = "gcol" + fieldName;
            col.Visible = true;
            col.Width = width;
            col.OptionsColumn.AllowEdit = false;

            col.AppearanceHeader.Options.UseTextOptions = true;
            col.AppearanceHeader.TextOptions.HAlignment =
                DevExpress.Utils.HorzAlignment.Center;

            col.AppearanceCell.Options.UseTextOptions = true;
            col.AppearanceCell.TextOptions.HAlignment = cellAlign;

            if (!string.IsNullOrEmpty(format))
            {
                col.DisplayFormat.FormatString = format;
                col.DisplayFormat.FormatType = DevExpress.Utils.FormatType.Numeric;
            }

            gvData.Columns.Add(col);
            band.Columns.Add(col);
        }

        private void AddColumn(
            GridBand band,
            string fieldName,
            string caption,
            int width,
            string format)
        {
            AddColumn(band, fieldName, caption, width, format, DevExpress.Utils.HorzAlignment.Center);
        }

        private void AddColumn(
            GridBand band,
            string fieldName,
            string caption,
            int width)
        {
            AddColumn(band, fieldName, caption, width, "", DevExpress.Utils.HorzAlignment.Center);
        }

        private void BeginProcess()
        {
            btnSearch.Enabled = btnClose.Enabled = false;
        }

        private void EndProcess()
        {
            btnSearch.Enabled = btnClose.Enabled = true;
        }

        private bool IsValidData()
        {
            if (uYearSemester.YearIDEditValue == null)
            {
                MessageManager.Warning("Bạn phải chọn niên học!");
                uYearSemester.Focus();
                return false;
            }

            return true;
        }

        #endregion

        #region Form Actions

        private void frmBangGioNghienCuuKhoaHoc_Load(object sender, EventArgs e)
        {
            CheckPermission();
            SetToolTip();
            InitGrid();
            new Thread(LoadReferenceData).Start();
        }

        private void frmBangGioNghienCuuKhoaHoc_KeyDown(object sender, KeyEventArgs e)
        {
            switch (e.KeyData)
            {
                case Keys.F3:
                    btnSearch_Click(sender, null);
                    break;

                case Keys.F5:
                    mnuItemRefresh_Click(sender, null);
                    break;
            }
        }

        private void btnSearch_Click(object sender, EventArgs e)
        {
            if (!IsValidData())
                return;

            BeginProcess();
            new Thread(LoadData).Start();
        }

        private void btnClose_Click(object sender, EventArgs e)
        {
            Close();
        }

        private void mnuItemRefresh_Click(object sender, EventArgs e)
        {
            bolIsRefresh = true;
            uSubjectGroup.RefrehData();
            uYearSemester.RefrehData();
            btnSearch_Click(sender, e);
        }

        private void btnPrint_Click(object sender, EventArgs e)
        {
            if (dtbData == null || dtbData.Rows.Count == 0)
            {
                MessageManager.Warning("Không có dữ liệu để in!");
                return;
            }

            gcData.ShowPrintPreview();
        }

        private void mnuItemExportToExcel_Click(object sender, EventArgs e)
        {
            gvData.QuickExportToExcel();
        }

        private void uSubjectGroup_EditValueChanged(object sender, EventArgs e)
        {
            string strCondition = "";

            if (uSubjectGroup.ScienceEditValue != null)
            {
                strCondition =
                    "ScienceID = '" +
                    uSubjectGroup.ScienceEditValue.ToString() +
                    "'";
            }

            if (uSubjectGroup.SubjectGroupEditValue != null)
            {
                strCondition +=
                    (strCondition == "" ? "" : " And ")
                    + " SubjectGroupID = '"
                    + uSubjectGroup.SubjectGroupEditValue.ToString()
                    + "'";
            }

            SIM_TeacherService.InitGridLookUpEdit(
                lookupTeacherID,
                strCondition
            );
        }

        #endregion
    }
}

